<?php if($activeTab==='hotel'&&$activeHotelProvider==='rakuten'&&!$rakutenErrors): ?><section class="result rakuten-result-section" data-provider-results="rakuten"><small>RAKUTEN TRAVEL RESULTS</small><h2><?= $h($rakutenValues['rakuten_destination']) ?>のホテル</h2><p class="rakuten-result-conditions"><?= $h($rakutenValues['rakuten_check_in']) ?> 〜 <?= $h($rakutenValues['rakuten_check_out']) ?>・大人<?= $h($rakutenValues['rakuten_adults']) ?>名・子供<?= $h($rakutenValues['rakuten_children']) ?>名</p><?php if($rakutenHotels): ?><div class="rakuten-hotel-results"><?php foreach($rakutenHotels as $rakutenIndex=>$rakutenHotel): ?><article class="rakuten-hotel-card"<?= $rakutenIndex>=5?' hidden data-extra-rakuten-hotel':'' ?>><div class="rakuten-hotel-photo-wrap"><?php if($rakutenHotel['image']!==''): ?><img class="rakuten-hotel-photo" src="<?= $h($rakutenHotel['image']) ?>" alt="<?= $h($rakutenHotel['name']) ?>" loading="lazy"><?php else: ?><div class="rakuten-hotel-photo rakuten-hotel-photo-placeholder">No image</div><?php endif ?></div><div class="rakuten-hotel-main"><h3><?= $h($rakutenHotel['name']) ?></h3><?php if($rakutenHotel['rating']!==''): ?><p class="rakuten-rating"><b><?= $h($rakutenHotel['rating']) ?></b> / 5<?php if($rakutenHotel['reviews']>0): ?> <span>（<?= number_format($rakutenHotel['reviews']) ?>件）</span><?php endif ?></p><?php endif ?><?php if($rakutenHotel['address']!==''): ?><p>📍 <?= $h($rakutenHotel['address']) ?></p><?php endif ?><?php if($rakutenHotel['access']!==''): ?><p><?= $h($rakutenHotel['access']) ?></p><?php endif ?><?php if($rakutenHotel['description']!==''): ?><p class="rakuten-description"><?= $h(mb_strimwidth($rakutenHotel['description'],0,130,'…')) ?></p><?php endif ?><?php if($rakutenHotel['facilities']): ?><p class="rakuten-facilities"><?= $h(implode(' / ',$rakutenHotel['facilities'])) ?></p><?php endif ?></div><aside class="rakuten-hotel-price"><?php if($rakutenHotel['price']>0): ?><small>1室1泊あたり参考</small><strong>¥<?= number_format($rakutenHotel['price']) ?>〜</strong><?php else: ?><p>料金は楽天トラベルでご確認ください</p><?php endif ?><a href="<?= $h($rakutenHotel['url']) ?>" target="_blank" rel="sponsored noopener">楽天トラベルで見る</a></aside></article><?php endforeach ?></div><?php if(count($rakutenHotels)>5): ?><button type="button" class="rakuten-results-toggle" data-step="5">もっと見る</button><?php endif ?><p class="price-note">料金・空室状況・プラン条件は検索時点から変わる場合があります。楽天トラベルで最終条件をご確認ください。</p><?php elseif($rakutenMessage !== ''): ?><div class="flight-offers-message"><?= $h($rakutenMessage) ?></div><?php endif ?></section><?php endif ?>
